using System;
using System.IdentityModel.Tokens.Jwt;

class Program {
    static void Main() {
        var handler = new JwtSecurityTokenHandler();
        var token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..hXfPb0HmiYa_pzzrhcPZn2bkGjmyNea249s2Ku8ev6A";
        var tokeObject = handler.ReadToken(token) as JwtSecurityToken;
        Console.WriteLine("Subject: " + (tokeObject.Subject ?? "NULL"));
        foreach(var claim in tokeObject.Claims) {
            Console.WriteLine(claim.Type + " = " + claim.Value);
        }
    }
}
